        compoundVariants: [
            {
                variant: 'default',
                severity: 'default',
                className: 'bg-primary hover:bg-primary-emphasis text-primary-contrast '
            },
            {
                variant: 'default',
                severity: 'secondary',
                className: 'bg-surface-100 hover:bg-surface-200 dark:bg-surface-800 dark:hover:bg-surface-700 '
            },
            {
