                iconOnly: true,
                size: 'normal',
                className: 'size-9'
            },
            {
                iconOnly: true,
                size: 'large',
                className: 'size-10.5'
            }
        ]
    }
);

function Button({ className, variant, size, severity, raised, rounded, iconOnly, ...props }: ButtonProps & VariantProps<typeof buttonVariants>) {
    return <PRButton className={cn(buttonVariants({ variant, size, severity, raised, rounded, iconOnly, className }))} {...props} />;
}

export { Button, buttonVariants };

import * as React from 'react';
import { ColorPickerAreaProps, ColorPickerEyeDropperProps, ColorPickerInputProps, ColorPickerRootProps, ColorPickerSliderProps, ColorPickerSwatchProps } from '@primereact/types/shared/colorpicker';
import { ColorPicker as ColorPickerPrime } from 'primereact/colorpicker';
import { cn } from '@/lib/utils';
import { inputTextVariants } from '@/components/ui/inputtext';

function ColorPicker({ ...props }: ColorPickerRootProps) {
    return <ColorPickerPrime.Root {...props} />;
}

function ColorPickerArea({ className, ...props }: ColorPickerAreaProps) {
    return (
        <ColorPickerPrime.Area className={cn('aspect-4/3 relative rounded-md min-w-3xs', className)} {...props}>
            <ColorPickerPrime.AreaBackground className="[background:var(--area-gradient)] size-full rounded-[inherit] shadow-[0px_0px_0px_1px_rgba(0,0,0,0.1)_inset]" />
            <ColorPickerPrime.AreaThumb className="[background:var(--thumb-background)] size-4 absolute top-(--thumb-position-top) left-(--thumb-position-left) -translate-y-1/2 -translate-x-1/2 border-2 border-white rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary" />
        </ColorPickerPrime.Area>
    );
}

function ColorPickerSlider({ className, ...props }: ColorPickerSliderProps) {
    return (
        <ColorPickerPrime.Slider className={cn('relative rounded-sm data-[orientation=vertical]:w-4 data-[orientation=horizontal]:h-4', className)} {...props}>
            <ColorPickerTransparencyGrid />
            <ColorPickerPrime.SliderTrack className="rounded-[inherit] [background:var(--slider-background)] absolute top-0 left-0 size-full z-2 shadow-[0px_0px_0px_1px_rgba(0,0,0,0.1)_inset]" />
            <ColorPickerPrime.SliderThumb className="absolute aspect-square data-[orientation=horizontal]:h-full data-[orientation=vertical]:w-full bg-(--thumb-background) border-2 border-white rounded-full z-3 top-(--thumb-position-top) left-(--thumb-position-left) -translate-x-1/2 -translate-y-1/2 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary" />
        </ColorPickerPrime.Slider>
    );
}

function ColorPickerSwatch({ className, ...props }: ColorPickerSwatchProps) {
    return (
        <ColorPickerPrime.Swatch className={cn('relative rounded-sm size-10 bg-white', className)} {...props}>
            <ColorPickerTransparencyGrid />
            <ColorPickerPrime.SwatchBackground className="absolute z-2 rounded-[inherit] size-full top-0 left-0 [background:var(--swatch-background)] shadow-[0px_0px_0px_1px_rgba(0,0,0,0.1)_inset]" />
        </ColorPickerPrime.Swatch>
    );
}

function ColorPickerTransparencyGrid({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
    return (
        <ColorPickerPrime.TransparencyGrid
            className={cn(
                'absolute rounded-[inherit] top-0 left-0 size-full z-1 bg-white bg-[conic-gradient(rgb(238,238,238)_0deg,rgb(238,238,238)_25%,transparent_0deg,transparent_50%,rgb(238,238,238)_0deg,rgb(238,238,238)_75%,transparent_0deg)] bg-size-[0.5rem_0.5rem]',
                className
            )}
            {...props}
        />
    );
}

function ColorPickerInput({ className, ...props }: ColorPickerInputProps) {
    return <ColorPickerPrime.Input className={inputTextVariants({ className })} {...props} />;
}

function ColorPickerEyeDropper({ ...props }: ColorPickerEyeDropperProps) {
    return <ColorPickerPrime.EyeDropper {...props} />;
}

export { ColorPicker, ColorPickerArea, ColorPickerEyeDropper, ColorPickerInput, ColorPickerSlider, ColorPickerSwatch, ColorPickerTransparencyGrid };

import type { InputTextProps } from '@primereact/types/shared/inputtext';
import { cn } from '@/lib/utils';
import { cva, type VariantProps } from 'class-variance-authority';
import { InputText as PRInputText } from 'primereact/inputtext';
import * as React from 'react';

const inputTextVariants = cva(
    ' rounded-lg w-full min-w-0 disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-60 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary-500/20 dark:focus-visible:outline-primary-500/30 aria-invalid:outline-red-500/20 dark:aria-invalid:outline-red-500/30 placeholder:text-surface-500 dark:placeholder:text-surface-400 aria-invalid:placeholder:text-red-500 dark:aria-invalid:placeholder:text-red-400 aria-invalid:text-red-500 dark:aria-invalid:text-red-400',
    {
        variants: {
            variant: {
                filled: 'bg-surface-100 dark:bg-surface-800 aria-invalid:bg-red-500/10 transition-[color,box-shadow]',
                outlined: 'bg-transparent border border-surface shadow-xs aria-invalid:border-red-500 transition-[color,box-shadow,border-color]'
            },
            size: {
                small: 'h-8 px-2.5 py-1 text-sm',
                normal: 'h-9 px-3 py-1.5 text-base',
                large: 'h-10.5 px-3.5 py-2 text-lg'
            }
        },
        defaultVariants: {
            variant: 'outlined',
            size: 'normal'
        }
    }
);

function InputText({ className, size, variant, invalid, ...props }: InputTextProps & VariantProps<typeof inputTextVariants>) {
    return <PRInputText className={cn(inputTextVariants({ size, variant, className }))} {...props} aria-invalid={invalid} />;
}

export { InputText, inputTextVariants };

'use client';
import { PaginatorEllipsisProps, PaginatorFirstProps, PaginatorLastProps, PaginatorNextProps, PaginatorPageProps, PaginatorPagesInstance, PaginatorPagesProps, PaginatorPrevProps, PaginatorRootProps } from '@primereact/types/shared/paginator';
import { cn } from '@/lib/utils';
import { Paginator as PrimePaginator } from 'primereact/paginator';
import * as React from 'react';

function Paginator({ className, ...props }: PaginatorRootProps) {
    return <PrimePaginator.Root className={cn('flex items-center gap-2', className)} {...props} />;
}

function PaginatorPages({ className, ...props }: PaginatorPagesProps) {
    return (
        <PrimePaginator.Pages className={cn('flex items-center gap-2', className)} {...props}>
            {({ paginator }: PaginatorPagesInstance) => paginator?.pages.map((page, index) => (page.type === 'page' ? <PaginatorPage key={index} value={page.value} /> : <PaginatorEllipsis key={index} />))}
        </PrimePaginator.Pages>
    );
}

function PaginatorPage({ className, ...props }: PaginatorPageProps) {
    return <PrimePaginator.Page className={cn('cursor-pointer size-9 rounded-lg border border-surface hover:bg-surface-100 dark:hover:bg-surface-800 transition-colors', className)} {...props} />;
}

function PaginatorEllipsis({ className, ...props }: PaginatorEllipsisProps) {
    return <PrimePaginator.Ellipsis className={cn('', className)} {...props} />;
}

function PaginatorFirst({ className, ...props }: PaginatorFirstProps) {
    return <PrimePaginator.First className={cn('', className)} {...props} />;
}

function PaginatorLast({ className, ...props }: PaginatorLastProps) {
    return <PrimePaginator.Last className={cn('', className)} {...props} />;
}

function PaginatorPrev({ className, ...props }: PaginatorPrevProps) {
    return <PrimePaginator.Prev className={cn('', className)} {...props} />;
}

function PaginatorNext({ className, ...props }: PaginatorNextProps) {
    return <PrimePaginator.Next className={cn('', className)} {...props} />;
}

export { Paginator, PaginatorFirst, PaginatorLast, PaginatorNext, PaginatorPage, PaginatorPages, PaginatorPrev };

import type { SwitchRootProps } from '@primereact/types/shared/switch';
import { cn } from '@/lib/utils';
import { Switch as SwitchPrime } from 'primereact/switch';
import * as React from 'react';

function Switch({ className, invalid, children, ...props }: SwitchRootProps & { children?: React.ReactNode }) {
    return (
        <SwitchPrime.Root
            className={cn(
                'peer group relative disabled:pointer-events-none disabled:opacity-60',
                '[&>input]:size-full [&>input]:whitespace-nowrap [&>input]:outline-none [&>input]:absolute [&>input]:top-0 [&>input]:left-0 [&>input]:opacity-0',
                className
            )}
            aria-invalid={invalid}
            {...props}
        >
            <SwitchPrime.Control
                aria-invalid={invalid}
                className={cn(
                    'w-10 h-6 border-2 border-transparent bg-surface-200 hover:bg-surface-300 dark:bg-surface-700 aria-invalid:bg-red-500/50 dark:hover:bg-surface-600 group-data-[p-checked=true]:bg-primary group-data-[p-checked=true]:hover:bg-primary-emphasis rounded-full transition-[background,box-shadow] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary-500/50 aria-invalid:focus-visible:outline-red-500'
                )}
            >
                <SwitchPrime.Thumb className={cn('h-full aspect-square group-data-[p-checked=true]:translate-x-[calc(100%-3px)] bg-primary-contrast rounded-full transition-[translate,width] pointer-events-none')} children={children} />
            </SwitchPrime.Control>
        </SwitchPrime.Root>
    );
}

export { Switch };

import { cn as primeuixcn } from '@primeuix/utils';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: Parameters<typeof primeuixcn>) {
    return twMerge(primeuixcn(inputs));
}
